<div class="page" id="pg-despesas">
<div class="shdr"><span style="color:var(--mt);font-size:11px">Despesas operacionais e compras avulsas</span><button class="btn bp" onclick="openM('m-desp')">+ Despesa</button><button class="btn bw btn-sm no-print" onclick="abrirImportacao('despesas')" title="Importar planilha CSV">📥 Importar</button><button class="btn bd btn-sm no-print" onclick="limparModulo('despesas')" title="Apagar TODOS os dados desta aba (somente admin)">🗑 Limpar Tudo</button></div>
<div style="margin-bottom:10px"><input oninput="filtrarTabela(this,'desp-tb')" placeholder="🔍 Buscar por descrição, fornecedor, placa..." style="width:100%;max-width:400px;padding:9px 12px;border:1px solid var(--br);border-radius:8px;background:var(--cd2);color:var(--tx);font-size:13px" type="search"/></div>
<div class="krow c3"><div class="kpi rd"><div class="klbl">Total Despesas</div><div class="kval" id="desp-tot">R$0</div><div class="ksub">período</div></div><div class="kpi yw"><div class="klbl">A Pagar</div><div class="kval" id="desp-ap">R$0</div><div class="ksub">pendentes</div></div><div class="kpi gn"><div class="klbl">Pagas</div><div class="kval" id="desp-pg">R$0</div><div class="ksub">quitadas</div></div></div>
<div class="search-bar"><input id="desp-srch" oninput="rdDesp()" placeholder="🔍 Buscar descrição, placa, fornecedor..."/><select id="desp-fcat" onchange="rdDesp()"><option value="">Todas as Categorias</option><option>Combustível</option><option>Manutenção</option><option>Pneus</option><option>Seguros</option><option>IPVA/Licenciamento</option><option>Administrativo</option><option>Salários</option><option>Outros</option></select></div>
<div class="panel"><div class="tw"><table><thead><tr><th>Data</th><th>Descrição</th><th>Categoria</th><th>Placa</th><th>Doc.</th><th>Valor</th><th>Vencimento</th><th>Fluxo</th><th>Status</th><th></th></tr></thead><tbody id="desp-tb"></tbody></table></div></div>
</div>
